// Sauna round timer. (c) 2026 DIVELUX Inc. MIT License. https://diveluxsaunahat.com
// In:  msg.payload = { cmd: "start", rounds, heat, rest, cooldown }  or  { cmd: "stop" }
// Out: one message at the start of each part, then one when the session is done:
//      msg.topic = "sauna/phase", msg.payload = { kind, round, rounds, minutes, index, parts, label }
// Rules are the same as the <sauna-timer> element: 1-6 rounds, 1-35 min per round,
// 1-30 min of break, a final cool-down that defaults to the break length.
// These are bounds for a timer, not advice. Not medical advice.
const p = (msg.payload && typeof msg.payload === 'object') ? msg.payload : { cmd: String(msg.payload || '') };
const cmd = String(p.cmd || '').toLowerCase();

function clamp(v, min, max, def) {
    const n = typeof v === 'number' ? v : parseFloat(v);
    if (!isFinite(n)) return def;
    return Math.min(max, Math.max(min, Math.round(n)));
}

function stop(reason) {
    const t = context.get('timer');
    if (t) clearTimeout(t);
    context.set('timer', null);
    context.set('session', null);
    node.status({ fill: 'grey', shape: 'ring', text: reason || 'stopped' });
}

if (cmd === 'stop') {
    const was = context.get('session');
    stop('stopped');
    if (!was) return null;
    return { topic: 'sauna/phase', payload: { kind: 'stopped', label: 'Session stopped' } };
}
if (cmd !== 'start') {
    node.warn('round timer: send { "cmd": "start" } or { "cmd": "stop" }');
    return null;
}

const rounds = clamp(p.rounds, 1, 6, 3);
const heat = clamp(p.heat, 1, 35, 10);
const rest = clamp(p.rest, 1, 30, 10);
const cooldown = clamp(p.cooldown, 1, 30, rest);
// One "minute" in ms. Leave it at 60000; a smaller number speeds the timer up for a test run.
const minuteMs = clamp(msg.minuteMs, 10, 60000, 60000);

const parts = [];
for (let i = 1; i <= rounds; i++) {
    parts.push({ kind: 'heat', round: i, minutes: heat, label: 'Round ' + i + ' of ' + rounds });
    if (i < rounds) parts.push({ kind: 'rest', round: i, minutes: rest, label: 'Break' });
}
parts.push({ kind: 'cool', round: rounds, minutes: cooldown, label: 'Final cool-down' });

stop('starting');
const id = Date.now();
context.set('session', id);

function run(index) {
    if (context.get('session') !== id) return; // stopped or restarted
    if (index >= parts.length) {
        context.set('timer', null);
        context.set('session', null);
        node.status({ fill: 'green', shape: 'dot', text: 'done' });
        node.send({ topic: 'sauna/phase', payload: { kind: 'done', round: rounds, rounds: rounds, minutes: 0, index: index, parts: parts.length, label: 'Session done' } });
        return;
    }
    const part = parts[index];
    node.status({ fill: part.kind === 'heat' ? 'red' : 'blue', shape: 'dot', text: part.label + ', ' + part.minutes + ' min' });
    node.send({ topic: 'sauna/phase', payload: Object.assign({ rounds: rounds, index: index, parts: parts.length }, part) });
    context.set('timer', setTimeout(function () { run(index + 1); }, part.minutes * minuteMs));
}
run(0);
return null;

// Phase to notification text. (c) 2026 DIVELUX Inc. MIT License.
// In:  msg.payload from "Round timer".  Out: msg.title and msg.payload as plain text.
const ph = msg.payload || {};
let title, text;
switch (ph.kind) {
    case 'heat':
        title = ph.round === 1 ? 'Sauna session started' : 'Break over';
        text = ph.label + ': ' + ph.minutes + ' min in the heat.';
        break;
    case 'rest':
        title = 'Round ' + ph.round + ' of ' + ph.rounds + ' is over';
        text = 'Time to step out: ' + ph.minutes + ' min break.';
        break;
    case 'cool':
        title = 'Last round is over';
        text = 'Step out for the final cool-down: ' + ph.minutes + ' min.';
        break;
    case 'done':
        title = 'Sauna session done';
        text = 'All ' + ph.rounds + ' rounds and the final cool-down are over.';
        break;
    case 'stopped':
        title = 'Sauna timer stopped';
        text = 'The session was stopped.';
        break;
    default:
        return null;
}
msg.title = title;
msg.payload = title + '. ' + text;
return msg;

// "The sauna is ready" check. (c) 2026 DIVELUX Inc. MIT License.
// In:  msg.payload = a temperature reading (number or numeric string), in the same unit as the target.
// Out: one message when the reading first reaches the target. It re-arms only after the
//      room has cooled 5 degrees below the target, so a reading that wobbles around the
//      target does not send a stream of notifications.
// Target and unit come from flow context: saunaTarget (default 80) and saunaUnit (default "°C").
// Set them with the "Set target" change node.
const target = Number(flow.get('saunaTarget'));
const t = isFinite(target) && target > 0 ? target : 80;
const unit = flow.get('saunaUnit') || '°C';
const rearmBelow = t - 5;

const reading = typeof msg.payload === 'number' ? msg.payload : parseFloat(msg.payload);
if (!isFinite(reading)) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'not a number: ' + String(msg.payload).slice(0, 20) });
    return null;
}

let armed = context.get('armed');
if (armed === undefined) armed = true;

if (armed && reading >= t) {
    context.set('armed', false);
    node.status({ fill: 'green', shape: 'dot', text: 'ready ' + reading + ' ' + unit });
    msg.topic = 'sauna/ready';
    msg.title = 'Sauna is ready';
    msg.payload = 'Sauna is ready: ' + Math.round(reading) + ' ' + unit + ' (target ' + t + ' ' + unit + ').';
    return msg;
}
if (!armed && reading < rearmBelow) {
    context.set('armed', true);
}
node.status({ fill: armed ? 'red' : 'green', shape: armed ? 'ring' : 'dot', text: reading + ' ' + unit + (armed ? ' heating' : ' ready') });
return null;
